<template><div class="page-container queue-page"><PageHeader title="Hàng đợi kiểm duyệt AI" description="Đối soát kết quả mô hình, phân loại sai lệch và chọn mẫu huấn luyện có kiểm soát." :breadcrumbs="[{label:'Giám sát'},{label:'AI Review'}]"><template #actions><BaseButton variant="secondary" :loading="loading" @click="loadAll">Làm mới</BaseButton></template></PageHeader>
<section class="summary-grid" aria-label="Chất lượng mô hình"><BaseCard variant="kpi"><span>Chờ kiểm duyệt</span><strong>{{ summary.pendingReviews||0 }}</strong><small>Cần quyết định của người vận hành</small></BaseCard><BaseCard variant="kpi"><span>Đã kiểm duyệt</span><strong>{{ summary.totalReviewed||0 }}</strong><small>Precision proxy {{ summary.precisionProxy||0 }}%</small></BaseCard><BaseCard variant="kpi"><span>Sai dương / sai âm</span><strong>{{ summary.totalFalsePositive||0 }} / {{ summary.totalFalseNegative||0 }}</strong><small>Lỗi phân loại đã xác nhận</small></BaseCard><BaseCard variant="kpi"><span>Drift score</span><strong>{{ summary.recentDriftScore??'—' }}</strong><StatusBadge :status="summary.driftDetected?'critical':'success'" :label="summary.driftDetected?'Phát hiện drift':'Ổn định'" dot/></BaseCard></section>
<section class="queue-panel" aria-labelledby="ai-items-title"><header><div><h2 id="ai-items-title">Yêu cầu phán quyết</h2><p>{{ items.length }} bản ghi trong trang hiện tại</p></div><div class="filters"><BaseSelect id="ai-status-filter" v-model="statusFilter" aria-label="Lọc trạng thái" @update:model-value="commitFilters"><option value="">Tất cả trạng thái</option><option value="Pending">Chờ xử lý</option><option value="Reviewed">Đã xử lý</option></BaseSelect><BaseSelect id="ai-outcome-filter" v-model="outcomeFilter" aria-label="Lọc kết quả" @update:model-value="commitFilters"><option value="">Tất cả kết quả</option><option value="Confirmed">Xác nhận đúng</option><option value="FalsePositive">Sai dương</option><option value="FalseNegative">Sai âm</option><option value="TrainingCandidate">Mẫu huấn luyện</option></BaseSelect></div></header>
<DataTable :columns="columns" :rows="items" row-key="aiAdjudicationItemId" :loading="loadingItems" :error="itemsError" :permission-denied="permissionDenied" empty-title="Không có mục cần kiểm duyệt" empty-description="Thử thay đổi bộ lọc hoặc làm mới hàng đợi."><template #retry><BaseButton variant="secondary" @click="loadItems">Thử lại</BaseButton></template><template #cell-aiAdjudicationItemId="{value}">#{{ value }}</template><template #cell-source="{row}"><div class="stacked"><strong>{{ row.aiSource||'Không rõ nguồn' }}</strong><small>{{ row.modelVersion||'Không rõ phiên bản' }}</small></div></template><template #cell-confidence="{value}"><span class="confidence">{{ value!=null?`${(value*100).toFixed(0)}%`:'—' }}</span></template><template #cell-status="{value}"><StatusBadge :status="value==='Reviewed'?'success':'pending'" :label="value==='Reviewed'?'Đã xử lý':'Chờ xử lý'" dot/></template><template #cell-outcome="{value}"><StatusBadge v-if="value" :status="outcomeSemantic(value)" :label="outcomeLabel(value)"/><span v-else class="muted">Chưa có</span></template><template #actions="{row}"><BaseButton v-if="row.status==='Pending'" variant="ghost" size="small" @click="openReview(row)">Kiểm duyệt</BaseButton></template></DataTable></section>
<section class="queue-panel" aria-labelledby="ai-metrics-title"><header><div><h2 id="ai-metrics-title">Metric gần đây</h2><p>Dữ liệu hiệu năng do pipeline AI ghi nhận.</p></div></header><DataTable :columns="metricColumns" :rows="metrics" row-key="aiPerformanceMetricId" :loading="loadingMetrics" :error="metricsError" empty-title="Chưa có metric" empty-description="Metric sẽ xuất hiện sau chu kỳ đánh giá tiếp theo."><template #retry><BaseButton variant="secondary" @click="loadMetrics">Thử lại</BaseButton></template><template #cell-metricValue="{value}"><strong>{{ value }}</strong></template><template #cell-capturedAtUtc="{value}">{{ formatDate(value) }}</template></DataTable></section>
<BaseModal :open="Boolean(reviewTarget)" :title="`Kiểm duyệt #${reviewTarget?.aiAdjudicationItemId||''}`" :description="`${reviewTarget?.aiSource||'AI'} · ${reviewTarget?.modelVersion||'không rõ model'}`" @close="reviewTarget=null"><form id="ai-review-form" class="review-form" @submit.prevent="submitReview"><BaseField for-id="ai-review-outcome" label="Kết quả" required v-slot="field"><BaseSelect id="ai-review-outcome" v-model="reviewForm.outcome" :describedby="field.describedby"><option value="Confirmed">Xác nhận đúng</option><option value="FalsePositive">Sai dương</option><option value="FalseNegative">Sai âm</option><option value="TrainingCandidate">Mẫu huấn luyện</option></BaseSelect></BaseField><BaseField for-id="ai-review-note" label="Ghi chú" :counter="`${reviewForm.reviewNote.length}/500`" v-slot="field"><BaseTextarea id="ai-review-note" v-model="reviewForm.reviewNote" maxlength="500" :describedby="field.describedby" placeholder="Căn cứ cho quyết định kiểm duyệt"/></BaseField><p v-if="reviewError" class="form-error" role="alert">{{ reviewError }}</p></form><template #footer><BaseButton variant="secondary" :disabled="busy" @click="reviewTarget=null">Hủy</BaseButton><BaseButton type="submit" form="ai-review-form" :loading="busy">Gửi phán quyết</BaseButton></template></BaseModal></div></template>
<script setup>import{computed,onMounted,reactive,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{enterpriseApi}from'../services/enterpriseSecurityApi';import BaseButton from'../components/ui/BaseButton.vue';import BaseCard from'../components/ui/BaseCard.vue';import BaseField from'../components/ui/BaseField.vue';import BaseModal from'../components/ui/BaseModal.vue';import BaseSelect from'../components/ui/BaseSelect.vue';import BaseTextarea from'../components/ui/BaseTextarea.vue';import DataTable from'../components/ui/DataTable.vue';import PageHeader from'../components/ui/PageHeader.vue';import StatusBadge from'../components/ui/StatusBadge.vue';import{useToasts}from'../composables/useToasts';
const route=useRoute(),router=useRouter(),{success}=useToasts();const items=ref([]),metrics=ref([]),summary=ref({}),loadingItems=ref(true),loadingMetrics=ref(true),itemsError=ref(''),metricsError=ref(''),permissionDenied=ref(false),busy=ref(false),statusFilter=ref(''),outcomeFilter=ref(''),reviewTarget=ref(null),reviewForm=reactive({outcome:'Confirmed',reviewNote:''}),reviewError=ref('');const loading=computed(()=>loadingItems.value||loadingMetrics.value);const columns=[{key:'aiAdjudicationItemId',label:'ID'},{key:'source',label:'Nguồn / Model'},{key:'confidence',label:'Độ tin cậy'},{key:'status',label:'Trạng thái'},{key:'outcome',label:'Kết quả'}],metricColumns=[{key:'metricName',label:'Metric'},{key:'metricValue',label:'Giá trị'},{key:'aiSource',label:'Nguồn'},{key:'capturedAtUtc',label:'Thời gian'}];function applyQuery(){statusFilter.value=['Pending','Reviewed'].includes(String(route.query.status))?String(route.query.status):'';outcomeFilter.value=String(route.query.outcome||'')}function commitFilters(){router.replace({query:{status:statusFilter.value||undefined,outcome:outcomeFilter.value||undefined}})}async function loadSummary(){try{summary.value=(await enterpriseApi.getAiMetricsSummary()).data||{}}catch{summary.value={}}}async function loadItems(){loadingItems.value=true;itemsError.value='';permissionDenied.value=false;try{const params={page:1,pageSize:100,status:statusFilter.value||undefined,outcome:outcomeFilter.value||undefined};items.value=(await enterpriseApi.getAiAdjudications(params)).data.items||[]}catch(error){items.value=[];if(error.response?.status===403)permissionDenied.value=true;else itemsError.value=error.response?.data?.message||'Không thể tải hàng đợi kiểm duyệt.'}finally{loadingItems.value=false}}async function loadMetrics(){loadingMetrics.value=true;metricsError.value='';try{const data=(await enterpriseApi.getAiMetrics({limit:30})).data;metrics.value=Array.isArray(data)?data:[]}catch(error){metrics.value=[];metricsError.value=error.response?.data?.message||'Không thể tải metric AI.'}finally{loadingMetrics.value=false}}async function loadAll(){await Promise.all([loadItems(),loadMetrics(),loadSummary()])}function openReview(item){reviewTarget.value=item;Object.assign(reviewForm,{outcome:'Confirmed',reviewNote:''});reviewError.value=''}async function submitReview(){if(!reviewTarget.value)return;busy.value=true;reviewError.value='';try{await enterpriseApi.reviewAiAdjudication(reviewTarget.value.aiAdjudicationItemId,{...reviewForm});reviewTarget.value=null;success('Đã ghi nhận phán quyết AI');await loadAll()}catch(error){reviewError.value=error.response?.data?.message||'Không thể gửi phán quyết. Nội dung nhập vẫn được giữ lại.'}finally{busy.value=false}}function outcomeSemantic(value){return value==='Confirmed'?'success':['FalsePositive','FalseNegative'].includes(value)?'danger':'info'}function outcomeLabel(value){return{Confirmed:'Xác nhận đúng',FalsePositive:'Sai dương',FalseNegative:'Sai âm',TrainingCandidate:'Mẫu huấn luyện'}[value]||value}function formatDate(value){return value?new Date(value).toLocaleString('vi-VN'):'—'}onMounted(()=>{applyQuery();loadAll()});watch(()=>route.query,()=>{applyQuery();loadItems()},{deep:true})</script>
<style scoped>.queue-page{display:grid;gap:var(--space-6)}.summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--space-4)}.summary-grid span,.summary-grid small{display:block;color:var(--text-secondary);font-size:var(--type-caption-size)}.summary-grid strong{display:block;margin-block:var(--space-2);font-size:var(--type-h2-size)}.queue-panel{display:grid;gap:var(--space-4)}.queue-panel>header{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--space-4)}.queue-panel h2{font-size:var(--type-h2-size)}.queue-panel header p,.muted,.stacked small{color:var(--text-muted);font-size:var(--type-body-size)}.filters{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-2);width:min(100%,440px)}.stacked,.review-form{display:grid;gap:var(--space-2)}.confidence{font-weight:800}.form-error{padding:var(--space-3);border:1px solid var(--status-danger-border);border-radius:var(--radius-control);background:var(--status-danger-bg);color:var(--status-danger-text)}@media(max-width:900px){.summary-grid{grid-template-columns:repeat(2,1fr)}.queue-panel>header{align-items:stretch;display:grid}.filters{width:100%}}@media(max-width:640px){.summary-grid,.filters{grid-template-columns:1fr}}</style>
